/**
 * Plan documents. The brief says what to build first; these six markdown
 * documents carry the engineering behind it. Each one is generated by the
 * model on demand from the idea plus the agreed brief, then lives in the
 * store where it can be edited, deleted, or joined by custom notes.
 *
 * Section shapes follow the industry-standard outlines for each document
 * type (PRD/TRD per common product practice; AFD/BSD/IPD per this
 * workspace's own definitions), tuned so every section forces a decision
 * instead of restating the idea.
 */

import type { Project } from "./types";
import {
  PRD_GUIDANCE,
  PRD_MIN_WORDS,
  PRD_SECTIONS,
  buildPrdFallback,
  buildUnifiedPrdPrompt,
} from "./prd-contract";

export type DocKind = "prd" | "trd" | "afd" | "dbd" | "bsd" | "ipd";

export interface DocTypeInfo {
  kind: DocKind;
  label: string;
  full: string;
  blurb: string;
  filename: string;
}

export const DOC_TYPES: DocTypeInfo[] = [
  {
    kind: "prd",
    label: "PRD",
    full: "Product Requirements Document",
    blurb: "Problem, users, core flow, and what ships first.",
    filename: "prd.md",
  },
  {
    kind: "trd",
    label: "TRD",
    full: "Technical Requirements Document",
    blurb: "Stack, architecture, and engineering constraints.",
    filename: "trd.md",
  },
  {
    kind: "afd",
    label: "AFD",
    full: "App Flow Documentation",
    blurb: "Screen-by-screen flows with a flow diagram.",
    filename: "afd.md",
  },
  {
    kind: "dbd",
    label: "DBD",
    full: "Database Design",
    blurb: "Entities, columns, relations, and an ER diagram.",
    filename: "dbd.md",
  },
  {
    kind: "bsd",
    label: "BSD",
    full: "Backend Schema Documentation",
    blurb: "Endpoints, payloads, auth, and errors.",
    filename: "bsd.md",
  },
  {
    kind: "ipd",
    label: "IPD",
    full: "Implementation Plan Document",
    blurb: "Phases, milestones, build order, and risks.",
    filename: "ipd.md",
  },
];

export function docLabel(kind: string): string {
  if (kind === "note") return "Note";
  return DOC_TYPES.find((entry) => entry.kind === kind)?.label ?? kind;
}

export function docFullName(kind: string): string {
  if (kind === "note") return "Supporting note";
  return DOC_TYPES.find((entry) => entry.kind === kind)?.full ?? kind;
}

export function docFilename(kind: string, title: string): string {
  if (kind === "note") {
    const slug =
      title
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 40) || "note";
    return `${slug}.md`;
  }
  return DOC_TYPES.find((entry) => entry.kind === kind)?.filename ?? `${kind}.md`;
}

interface DocSpec {
  sections: string[];
  guidance: string[];
}

const SPECS: Record<DocKind, DocSpec> = {
  prd: {
    sections: [...PRD_SECTIONS],
    guidance: [...PRD_GUIDANCE],
  },
  trd: {
    sections: [
      "## System overview",
      "## Tech stack",
      "## Architecture",
      "## Data flow",
      "## API surface",
      "## Non-functional requirements",
      "## Risks and trade-offs",
    ],
    guidance: [
      "Tech stack is a table: layer, choice, and one sentence why it fits a solo developer building this exact app.",
      "Architecture names the real modules or routes of this app and how they talk to each other, not generic layered-diagram prose.",
      "Data flow traces one user action end to end: trigger, stores touched, and what the user sees after.",
      "Non-functional requirements carry numbers a developer can test: load-time budget, storage ceiling, and failure behavior when the model or network is unavailable.",
      "Risks and trade-offs name what was deliberately not chosen and what breaks first under load, with the mitigation for each.",
    ],
  },
  afd: {
    sections: [
      "## Flow overview",
      "## Flow diagram",
      "## Screen-by-screen flow",
      "## Navigation map",
      "## Empty, loading, and error states",
      "## Edge cases",
    ],
    guidance: [
      "The flow diagram is a ```mermaid flowchart TD block showing every screen as a node and every user action as a labeled edge, from first open to the value moment. Keep node labels short.",
      "Screen-by-screen flow is a table: Screen | Purpose | Key actions. Every screen from the diagram appears exactly once.",
      "Navigation map is a table: From | Trigger | To, covering back navigation and deep entry points, not just the happy path.",
      "Empty, loading, and error states describe what each screen shows before data arrives, when it fails, and when there is legitimately nothing to show.",
      "Edge cases name what happens on double submit, stale data after reload, and interrupted sessions.",
    ],
  },
  dbd: {
    sections: [
      "## Entities",
      "## Entity-relationship diagram",
      "## Relations",
      "## Indexes",
      "## Migration notes",
    ],
    guidance: [
      "Entities is one table per entity: Column | Type | Notes, including primary keys and defaults. Only entities this app actually stores.",
      "The entity-relationship diagram is a ```mermaid erDiagram block with every entity, its columns with types, and the real cardinalities between them.",
      "Relations restates each relationship in one sentence: which columns join, the cardinality, and delete behavior.",
      "Indexes name the exact columns indexed and the query each index serves.",
      "Migration notes describe how v1 ships the schema and what a later schema change costs.",
    ],
  },
  bsd: {
    sections: [
      "## Base URL and auth",
      "## Endpoints",
      "## Payload schemas",
      "## Error format",
      "## Rate limits",
    ],
    guidance: [
      "Endpoints is a table: Method | Path | Purpose | Auth. Every endpoint the app needs, including what the local-first client calls when it syncs.",
      "Payload schemas show one realistic request and response JSON per endpoint, using field names the app really uses.",
      "Auth states exactly how the caller proves identity on each endpoint and what happens without it.",
      "Error format gives the single error envelope with two realistic examples (validation failure, missing resource).",
      "Rate limits state the per-endpoint budget and the client behavior when it is exceeded.",
    ],
  },
  ipd: {
    sections: [
      "## Phases",
      "## Milestones",
      "## Build order",
      "## Estimates",
      "## Risks",
    ],
    guidance: [
      "Phases are vertical slices a solo developer can demo, each ending in something runnable. Each phase lists its exit check.",
      "Milestones pair each phase with its demo: what the reviewer clicks and what they should see.",
      "Build order is a numbered dependency chain: each step names what it unblocks next, so nothing is built before its foundation.",
      "Estimates use relative sizes (S/M/L) against the phase list, with the single biggest unknown called out.",
      "Risks name what slips the plan, the early warning sign for each, and the fallback that keeps the demo shippable.",
    ],
  },
};

export function buildDocPrompt(
  kind: DocKind,
  project: Project,
  brief: string,
): string {
  // The PRD uses the single unified contract (same headings, order, and
  // wizard/stack context as runPlan and first-run preparation).
  if (kind === "prd") {
    const base = buildUnifiedPrdPrompt(project);
    const trimmed = brief.replace(/\s+/g, " ").trim().slice(0, 2000);
    if (!trimmed) return base;
    return [
      base,
      "",
      `Previous draft to improve (keep what works, fix what is missing): """${trimmed}"""`,
    ].join("\n");
  }
  const info = DOC_TYPES.find((entry) => entry.kind === kind);
  const spec = SPECS[kind];
  const trimmedBrief = brief.replace(/\s+/g, " ").trim().slice(0, 4000);
  return [
    `Write the ${info?.full ?? kind} for this app as markdown.`,
    `Project name: "${project.name.trim() || "Untitled project"}".`,
    `The idea: "${project.idea.replace(/\s+/g, " ").trim().slice(0, 800)}".`,
    trimmedBrief
      ? `The agreed product brief (stay consistent with it, never contradict it): """${trimmedBrief}""".`
      : "",
    "",
    "Use exactly these sections, in this order:",
    ...spec.sections,
    "",
    "Content guidance:",
    ...spec.guidance.map((line) => `- ${line}`),
    "",
    "Rules:",
    "- 350 to 600 words plus required tables and diagrams. Concrete and specific to this product.",
    "- Tables carry real rows a developer can build from. Every row must hold product-specific content.",
    "- Mermaid blocks stay minimal and valid: short labels, no special characters that break parsing, no styling directives.",
    `- Start with '# ${info?.label ?? kind} — ${project.name.trim() || "Untitled project"}' and nothing else before it.`,
    "- No em dashes. No pricing, growth numbers, testimonials, or invented research.",
    "- Never write TODO, TBD, lorem ipsum, or bracketed placeholders like [insert X].",
    "- Return only the markdown, no fences or commentary.",
  ]
    .filter(Boolean)
    .join("\n");
}

/** A repair pass that names the missing contract instead of asking again. */
export function buildDocRepairPrompt(
  kind: DocKind,
  project: Project,
  brief: string,
  previous: string,
  missing: string[],
): string {
  return [
    buildDocPrompt(kind, project, brief),
    "",
    "YOUR PREVIOUS ANSWER WAS REJECTED",
    previous.trim()
      ? `It was missing or malformed at: ${missing.join(", ")}.`
      : "It was empty.",
    "Rewrite the whole document. Keep every required heading exactly as written, in order, with real product-specific content under each one.",
    "Do not apologise or explain what changed. Return only the corrected markdown.",
  ].join("\n");
}

/** A local outline with the right title and sections for this document. */
export function buildDocFallback(
  kind: string,
  project: Project,
  brief: string,
): string {
  if (kind === "prd") return buildPrdFallback(project);
  const info = DOC_TYPES.find((entry) => entry.kind === kind);
  const spec = kind in SPECS ? SPECS[kind as DocKind] : null;
  const name = project.name.trim() || "Untitled project";
  if (!info || !spec) {
    return `# ${info?.full ?? kind} — ${name}\n\n> Local outline. The model is unavailable, so this page is a starting point. Generate again for the full document.\n\n## Overview\n\n${project.idea.trim()}\n`;
  }
  const briefLine = brief.replace(/\s+/g, " ").trim().slice(0, 320);
  return [
    `# ${info.label} — ${name}`,
    "",
    "> Local outline. The model is unavailable, so the section frame below is real but the detail is not finished. Generate again when the model is back; this draft is never presented as a model answer.",
    "",
    "## Product context",
    "",
    project.idea.replace(/\s+/g, " ").trim().slice(0, 700),
    briefLine && briefLine !== project.idea.trim()
      ? `\nAgreed brief: ${briefLine}`
      : "",
    "",
    ...spec.sections.flatMap((section, index) => [
      section,
      "",
      index === 0
        ? `This section is waiting for the model. It will define the ${section.replace(/^##\s*/, "").toLowerCase()} for ${name} using the agreed brief.`
        : `- Decision needed: ${spec.guidance[index % spec.guidance.length]}`,
      "",
    ]),
  ].join("\n");
}

export interface DocQuality {
  ok: boolean;
  words: number;
  missing: string[];
}

function normalizeHeadingLine(line: string): string {
  return line.trim().replace(/\s+/g, ' ').toLowerCase();
}

/** Enforce the section contract before a model answer is stored. */
export function inspectDocMarkdown(kind: string, markdown: string): DocQuality {
  const spec = kind in SPECS ? SPECS[kind as DocKind] : null;
  const text = markdown.trim();
  const words = text ? text.split(/\s+/).length : 0;
  const missing: string[] = [];
  if (!text) {
    return { ok: false, words, missing: ['Empty document: no markdown to check.'] };
  }

  // Title: the first non-empty line must be a single-# heading.
  const lines = text.split('\n');
  const firstContent = lines.find((line) => line.trim().length > 0) ?? '';
  if (!/^#\s+\S/.test(firstContent.trim()) || /^##/.test(firstContent.trim())) {
    missing.push('Missing title: start with "# <project name>" and nothing else before it.');
  }

  // Real ## headings in document order.
  const headings = lines
    .map((line) => line.trim())
    .filter((line) => /^##\s+\S/.test(line))
    .map(normalizeHeadingLine);
  const required = (spec?.sections ?? []).map(normalizeHeadingLine);

  const counts = new Map<string, number>();
  for (const heading of headings) {
    counts.set(heading, (counts.get(heading) ?? 0) + 1);
  }

  let cursor = -1;
  required.forEach((section, index) => {
    const positions: number[] = [];
    headings.forEach((heading, at) => {
      if (heading === section) positions.push(at);
    });
    const original = spec?.sections[index] ?? section;
    if (!positions.length) {
      missing.push(`Missing section: ${original}`);
      return;
    }
    if ((counts.get(section) ?? 0) > 1) {
      missing.push(`Duplicate section: ${original} appears ${counts.get(section)} times, keep it exactly once`);
    }
    const firstAt = positions[0];
    if (firstAt <= cursor) {
      const prev = spec?.sections[index - 1] ?? 'the previous section';
      missing.push(`Out of order: ${original} must come after ${prev}`);
    } else {
      cursor = firstAt;
    }
    // Each required heading needs real content before the next heading.
    const lineIndex = lines.findIndex(
      (line) => normalizeHeadingLine(line) === section,
    );
    if (lineIndex !== -1) {
      let hasContent = false;
      for (let at = lineIndex + 1; at < lines.length; at += 1) {
        const trimmed = lines[at].trim();
        if (/^#{1,6}\s/.test(trimmed)) break;
        if (trimmed) {
          hasContent = true;
          break;
        }
      }
      if (!hasContent) missing.push(`Empty section: ${original} has no content under it`);
    }
  });

  // Length: the prompts ask for 350-600 words (PRD 220-380); 250 keeps the
  // gate useful without failing table- and mermaid-heavy documents.
  const minimum = PRD_MIN_WORDS;
  if (words < minimum) {
    missing.push(`Too short: ${words} words, need at least ${minimum}`);
  }

  if (/\b(?:TODO|TBD|lorem ipsum|placeholder|coming soon|\[insert [^\]]+\]|\[\s*\]|xxx+)\b/i.test(text)) {
    missing.push('Placeholder text: remove TODO, TBD, lorem ipsum, or bracketed placeholders like [insert X]');
  }

  return { ok: missing.length === 0, words, missing };
}

export function buildPrototypePrompt(project: Project, brief: string): string {
  const trimmedBrief = brief.replace(/\s+/g, " ").trim().slice(0, 4000);
  return [
    "Write one self-contained HTML file: a clickable-looking prototype of the app below.",
    `Project name: "${project.name.trim() || "Untitled project"}".`,
    `The idea: "${project.idea.replace(/\s+/g, " ").trim().slice(0, 800)}".`,
    trimmedBrief ? `The agreed product brief: """${trimmedBrief}""".` : "",
    "",
    "Rules:",
    "- One file. All CSS goes in a single <style> tag, all JS (if any) in a single <script> tag.",
    "- No external requests of any kind: no CDN links, no web fonts, no remote images. System fonts and inline SVG only.",
    "- Responsive: readable on a 390px phone and a 1280px desktop.",
    "- Real copy from the brief, no lorem ipsum, no bracketed placeholders.",
    "- The core screen from the brief must be visible without scrolling past a hero.",
    "- Return ONLY the HTML, no fences or commentary.",
  ]
    .filter(Boolean)
    .join("\n");
}

/** Strip the outer fence when the whole response is wrapped in one. Inner
 *  fences (mermaid diagrams, code samples) are left intact. */
export function parseDocMarkdown(raw: unknown): string {
  if (typeof raw !== "string") return "";
  let text = raw.trim();
  if (!text) return "";
  const outer = text.match(/^```(?:markdown|md)?\s*\n?([\s\S]*?)\s*```$/i);
  if (outer) text = outer[1].trim();
  // The model sometimes returns a bare mermaid block without fences.
  // Wrap it so it still renders as a diagram instead of plain text.
  if (/^mermaid\s+(flowchart|graph|erDiagram|sequenceDiagram|stateDiagram|classDiagram|gantt|pie|journey|mindmap|timeline)/i.test(text)) {
    text = "```mermaid\n" + text.replace(/^mermaid\s*/i, "") + "\n```";
  }
  return text;
}

/** Strip fences so the prototype file holds raw HTML. Models often wrap
 *  the file in prose ("Here's your page: ... Let me know ..."), so the
 *  fence is extracted wherever it sits; otherwise the document slice
 *  from <!doctype>/<html> to the last </html> is used. */
export function parsePrototypeHtml(raw: unknown): string {
  if (typeof raw !== "string") return "";
  const text = raw.trim();
  if (!text) return "";
  const fenced = text.match(/```(?:html)?\s*\n?([\s\S]*?)\s*```/i);
  if (fenced && fenced[1].trim()) return fenced[1].trim();
  const start = text.search(/<!doctype html|<html[\s>]/i);
  if (start !== -1) {
    const end = text.toLowerCase().lastIndexOf("</html>");
    const slice =
      end > start ? text.slice(start, end + "</html>".length) : text.slice(start);
    if (slice.trim()) return slice.trim();
  }
  return text;
}

/** Remove resources that would need the network, so a page always renders. */
export function stripExternalResources(html: string): string {
  return html
    .replace(/<link\b[^>]*\brel\s*=\s*["']?stylesheet["']?[^>]*>/gi, "")
    .replace(/<link\b[^>]*\bhref\s*=\s*["']https?:\/\/[^"']*["'][^>]*>/gi, "")
    .replace(
      /<script\b[^>]*\bsrc\s*=\s*["'](?:https?:)?\/\/[^"']*["'][^>]*>\s*<\/script\s*>/gi,
      "",
    )
    .replace(/@import\s+(?:url\()?["']?(?:https?:)?\/\/[^;]+;/gi, "");
}

/**
 * Make any model output a complete document. Models often return a bare
 * fragment or an <html> without a <body>, which can render blank inside
 * the canvas iframe. This wraps it so the body always exists.
 */
export function normalizePrototypeHtml(raw: unknown): string {
  let html = parsePrototypeHtml(raw);
  if (!html) return "";
  html = stripExternalResources(html);
  if (!/<html[\s>]/i.test(html)) {
    const title =
      html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.trim() ||
      "Prototype";
    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${title}</title>
</head>
<body>
${html}
</body>
</html>`;
  }
  if (!/<body[\s>]/i.test(html)) {
    const headClose = html.match(/<\/head\s*>/i);
    const htmlOpen = html.match(/<html[^>]*>/i);
    let before = "";
    let rest = html;
    if (headClose?.index !== undefined) {
      const at = headClose.index + headClose[0].length;
      before = html.slice(0, at);
      rest = html.slice(at);
    } else if (htmlOpen?.index !== undefined) {
      const at = htmlOpen.index + htmlOpen[0].length;
      before = html.slice(0, at);
      rest = html.slice(at);
    }
    rest = rest.replace(/<\/html\s*>\s*$/i, "");
    html = `${before}
<body>
${rest}
</body>
</html>`;
  }
  if (!/^\s*<!doctype html/i.test(html)) html = `<!DOCTYPE html>\n${html}`;
  return html.trim();
}

/** True when the markup smells like framework code instead of plain HTML. */
export function looksLikeFrameworkCode(html: string): boolean {
  return (
    /^\s*import\s+.+\s+from\s*["']/m.test(html) ||
    /\bfrom\s+["'](?:react|vue|svelte|next)["']/.test(html) ||
    /\bexport\s+(?:default|const|function)\b/.test(html) ||
    /\buse(?:State|Effect|Ref|Memo|Callback)\s*\(/.test(html) ||
    /<[A-Z][A-Za-z0-9]*\b[^>]*\b(?:className|onClick|onChange|onSubmit|key)\s*=/.test(
      html,
    ) ||
    /<[A-Z][A-Za-z0-9]*\b[^>]*=\s*\{/.test(html) ||
    /<template[\s>]/.test(html) ||
    /\sv-(?:if|for|bind|on|model|show|slot)\s*=/.test(html) ||
    /\s@[a-z]+\s*=/.test(html)
  );
}

/** True when the HTML holds enough visible copy to not render blank. */
export function hasVisibleContent(html: string): boolean {
  const body = html.match(/<body[\s>][\s\S]*?<\/body\s*>/i)?.[0] ?? html;
  const text = body
    .replace(/<script[\s>][\s\S]*?<\/script\s*>/gi, " ")
    .replace(/<style[\s>][\s\S]*?<\/style\s*>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (text.length < 140) return false;
  const blocks = body.match(
    /<(?:h1|h2|h3|p|button|a|li|td|label|input|section|article)\b/gi,
  );
  if (!blocks || blocks.length < 3) return false;
  // Content hidden until JavaScript runs still renders blank in a frame.
  if (
    /<(?:body|main|html)[^>]*style\s*=\s*["'][^"']*(?:opacity\s*:\s*0(?:[;\s"']|$)|visibility\s*:\s*hidden|display\s*:\s*none)/i.test(
      html,
    )
  ) {
    return false;
  }
  if (
    /(?:^|[},])\s*(?:body|html|main)\s*\{[^}]*(?:opacity\s*:\s*0(?:[;\s}]|$)|visibility\s*:\s*hidden|display\s*:\s*none)/i.test(
      html,
    )
  ) {
    return false;
  }
  return true;
}

/** Words too common to prove a planned block is present. */
const COVERAGE_STOP = new Set([
  "with",
  "from",
  "that",
  "this",
  "your",
  "into",
  "over",
  "each",
  "then",
  "than",
  "and",
  "for",
  "the",
  "one",
  "all",
  "per",
  "not",
  "are",
  "its",
  "has",
  "have",
  "plus",
  "show",
  "shows",
]);

/**
 * Which planned blocks the rendered page does not mention. Used as a
 * quality gate: a page that skipped half its blocks gets one repair pass.
 */
export function missingPageSections(
  html: string,
  sections: string[] = [],
): string[] {
  if (!sections.length) return [];
  const body = html.match(/<body[\s>][\s\S]*?<\/body\s*>/i)?.[0] ?? html;
  const text = body
    .replace(/<script[\s>][\s\S]*?<\/script\s*>/gi, " ")
    .replace(/<style[\s>][\s\S]*?<\/style\s*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .toLowerCase();
  return sections.filter((section) => {
    const words = section
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter((word) => word.length > 3 && !COVERAGE_STOP.has(word));
    if (!words.length) return false;
    return !words.some((word) => text.includes(word));
  });
}
